import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const modules = new Map();

function collect(file) {
    file = path.resolve(file);
    if (modules.has(file)) return;
    let source = fs.readFileSync(file, 'utf8');
    const imports = [];
    source = source.replace(/import\s*\{([^}]+)\}\s*from\s*['"]([^'"]+)['"];?/g, (_, names, spec) => {
        const dep = path.resolve(path.dirname(file), spec);
        collect(dep);
        imports.push(`const { ${names.trim().replace(/\s+as\s+/g, ': ')} } = require(${JSON.stringify(id(dep))});`);
        return '';
    });
    const exports = [];
    source = source.replace(/export\s+(function|class|const|let|var)\s+([A-Za-z_$][\w$]*)/g, (_, kind, name) => {
        exports.push(name);
        return `${kind} ${name}`;
    });
    source = source.replace(/export\s+const\s+\{([^}]+)\}/g, (_, names) => {
        for (const part of names.split(',')) exports.push(part.trim().split(':')[0].trim());
        return `const {${names}}`;
    });
    source = source.replace(/export\s*\{([^}]+)\};?/g, (_, names) => {
        for (const part of names.split(',')) exports.push(part.trim().split(/\s+as\s+/)[0]);
        return '';
    });
    const assignments = [...new Set(exports)].map(name => `exports.${name} = ${name};`).join('\n');
    modules.set(file, `${imports.join('\n')}\n${source}\n${assignments}`);
}

function id(file) { return path.relative(root, file).replaceAll('\\', '/'); }

const entry = path.join(root, 'src/app.js');
collect(entry);
const body = [...modules].map(([file, source]) => `${JSON.stringify(id(file))}: function(require, exports) {\n${source}\n}`).join(',\n');
const bundle = `/* Generated by tools/build-bundle.mjs. */\n(function(){\n'use strict';\nconst modules = {\n${body}\n};\nconst cache = {};\nfunction require(id){ if(cache[id]) return cache[id]; const exports = {}; cache[id] = exports; modules[id](require, exports); return exports; }\nrequire('src/app.js');\n})();\n`;
fs.writeFileSync(path.join(root, 'app.bundle.js'), bundle);
console.log(`Built app.bundle.js (${Math.round(bundle.length / 1024)} KiB, ${modules.size} modules)`);
